entity Prob_6_39_Counter_BEH_vhdl is	port (Count: buffer bit_vector (2 downto 0); Clock, reset_b: in bit);end Prob_6_39_Counter_BEH_vhdl;architecture Behavioral of Prob_6_39_Counter_BEH_vhdl is begin	process (Clock, reset_b) begin	if (reset_b = '0') then Count <= "000";    	elsif Clock'event and Clock = '1' then			case (Count) is      				when "000" =>	Count <= "001";      				when "001" =>	Count <= "010";      				when "010" =>	Count <= "100";				when "011" =>	Count <= "100";				when "100" =>	Count <= "101";				when "101" =>	Count <= "110";				when "110" =>	Count <= "000";      				when "111" =>	Count <= "000";      				when others =>	Count <= "000";			end case;
		end if;	end process;end Behavioral;